create table xxventuri.xxeba_sales_customer_details (
    details_id                 number not null enable,
    customer_id                number,
    mode_of_delivery           varchar2(255 byte),
    credit_days                number,
    credit_limit               number,
    credit_currency            varchar2(20 byte),
    grace_days                 number,
    enquiry_customer           varchar2(255 byte),
    enquiry_supplier           varchar2(255 byte),
    enquiry_competitor         varchar2(255 byte),
    enquiry_employee           varchar2(255 byte),
    introduced_by              varchar2(255 byte),
    verified_by                number,
    expected_business          number,
    expected_business_currency varchar2(20 byte),
    credit_terms_rec           number,
    credit_limit_rec           number,
    credit_limit_currency      varchar2(20 byte),
    grace_days_rec             number,
    visit_frequency_rec        varchar2(255 byte),
    assigned_to                number,
    comments                   varchar2(500 byte),
    recommended_by             number,
    status                     varchar2(1 byte),
    created_by                 varchar2(255 byte),
    creation_date              timestamp(6),
    updated_by                 varchar2(255 byte),
    update_date                timestamp(6),
    schedule_frequency         varchar2(1 byte)
);

alter table xxventuri.xxeba_sales_customer_details
    add constraint xxeba_sales_cust_details_pk primary key ( details_id )
        using index enable;


